import re
from datetime import datetime

_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_EPOCH = datetime(1970, 1, 1)
_GMAIL_DOMAINS = ("gmail.com", "googlemail.com")
_DIGITS = "0123456789"


def _normalize_email(raw):
    s = (raw or "").strip()
    m = re.search(r"<([^<>]*)>", s)
    if m:
        s = m.group(1)
    s = s.strip().lower()
    if s.count("@") == 1:
        local, domain = s.split("@")
        if domain in _GMAIL_DOMAINS:
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"
        s = f"{local}@{domain}"
    return s


def _valid_email(e):
    if e.count("@") != 1:
        return False
    local, domain = e.split("@")
    return bool(local) and "." in domain and not domain.startswith(".") and not domain.endswith(".")


def _normalize_phone(raw):
    s = (raw or "").strip().lower()
    markers = [p for p in (s.find("x"), s.find("ext"), s.find("#")) if p != -1]
    if markers:
        s = s[:min(markers)]
    digits = "".join(c for c in s if c in _DIGITS)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    return digits


def _valid_phone(d):
    return len(d) == 10 and d[0] not in "01"


def _normalize_zip(raw):
    z = (raw or "").strip()
    m = re.fullmatch(r"([0-9]{5})-[0-9]{4}", z)
    if m:
        z = m.group(1)
    if re.fullmatch(r"[0-9]{4}", z):
        z = "0" + z
    return z if re.fullmatch(r"[0-9]{5}", z) else ""


def _normalize_name(raw):
    s = (raw or "").strip()
    if s.isupper() or s.islower():
        s = s.title()
    return s


def _parse_updated(raw):
    s = (raw or "").strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    raise ValueError(f"Unrecognized 'updated' value: {raw!r}")


def _is_opted_out(raw):
    return (raw or "").strip().lower() in {"y", "yes", "true", "1"}


def _parse_tags(raw):
    return {t.strip().lower() for t in re.split(r"[;,]", raw or "") if t.strip()}


def dedupe_contacts(rows):
    # 1. Normalize each row and drop rows with no valid email or phone.
    recs = []
    for row in rows:
        email = _normalize_email(row.get("email", ""))
        if not _valid_email(email):
            email = ""
        phone = _normalize_phone(row.get("phone", ""))
        if not _valid_phone(phone):
            phone = ""
        if not email and not phone:
            continue
        source = (row.get("source", "") or "").strip().lower()
        recs.append({
            "first_name": _normalize_name(row.get("first_name", "")),
            "last_name": _normalize_name(row.get("last_name", "")),
            "zip": _normalize_zip(row.get("zip", "")),
            "email": email,
            "phone": phone,
            "source": source,
            "manual": source == "manual",
            "tags": _parse_tags(row.get("tags", "")),
            "opted_out": _is_opted_out(row.get("opted_out", "")),
            "updated": _parse_updated(row.get("updated", "")),
        })

    # 2. Union-find: link rows sharing a valid email, or a valid phone plus a
    #    non-empty last name (case-insensitive). Union-find gives transitivity.
    n = len(recs)
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    first_seen = {}

    def link(key, i):
        if key in first_seen:
            union(first_seen[key], i)
        else:
            first_seen[key] = i

    for i, r in enumerate(recs):
        if r["email"]:
            link(("email", r["email"]), i)
        last_key = r["last_name"].lower()
        if r["phone"] and last_key:
            link(("phone", r["phone"], last_key), i)

    # 3. Group rows. Indices within a group are ascending, so idx[0] is the
    #    earliest row; sorting groups by idx[0] orders people by first appearance.
    groups = {}
    for i in range(n):
        groups.setdefault(find(i), []).append(i)
    ordered_groups = sorted(groups.values(), key=lambda idx: idx[0])

    def rank(i):
        # Manual rows first, then most recent updated, then earlier input row.
        return (0 if recs[i]["manual"] else 1,
                -(recs[i]["updated"] - _EPOCH).total_seconds(),
                i)

    def pick(idx, field):
        candidates = [i for i in idx if recs[i][field]]
        if not candidates:
            return ""
        return recs[min(candidates, key=rank)][field]

    # 4. Build one output record per person.
    output = []
    for idx in ordered_groups:
        all_tags = set().union(*(recs[i]["tags"] for i in idx))
        output.append({
            "first_name": pick(idx, "first_name"),
            "last_name": pick(idx, "last_name"),
            "zip": pick(idx, "zip"),
            "email": pick(idx, "email"),
            "phone": pick(idx, "phone"),
            "source": pick(idx, "source"),
            "tags": ";".join(sorted(all_tags)),
            "opted_out": "Y" if any(recs[i]["opted_out"] for i in idx) else "N",
            "updated": max(recs[i]["updated"] for i in idx).strftime("%Y-%m-%d"),
        })
    return output
```

Notes:

- **Opt-outs are flagged, not removed.** Filter on `opted_out == "Y"` in the send step. Because a person is marked "Y" if any of their rows opted out, a merged contact with one opt-out row is excluded entirely. That's the conservative choice for this send.
- **Bad dates raise an error.** If an `updated` value doesn't match one of the three formats, the function raises `ValueError` with the value rather than guessing its position in the ordering.
